<section class="page-heading"><div><p class="eyebrow">Inventory</p><h1>Products</h1><p class="subtitle">Manage prices, stock, and product availability.</p></div><a class="button" href="<?= site_url('products/new') ?>">Create Product</a></section>
<?php if (session()->getFlashdata('message')): ?><p class="success"><?= esc(session()->getFlashdata('message')) ?></p><?php endif; ?><div class="table-card"><div class="table-scroll"><table><thead><tr><th>Image</th><th>Name</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td data-label="Image"><?php if($p['image']): ?><img class="product-image" src="<?= base_url('uploads/'.rawurlencode($p['image'])) ?>" alt="<?= esc($p['name']) ?>"><?php else: ?>No image<?php endif; ?></td><td data-label="Name"><?= esc($p['name']) ?></td><td data-label="Price">₱<?= number_format((float)$p['price'],2) ?></td><td data-label="Stock"><?= esc($p['stock_quantity']) ?></td><td data-label="Status"><?= $p['archived_at'] ? 'Archived' : 'Active' ?></td><td data-label="Actions"><a class="button button-small button-secondary" href="<?= site_url('products/'.$p['id'].'/edit') ?>">Edit</a><?php if(!$p['archived_at']): ?><form class="inline-form" method="post" action="<?= site_url('products/'.$p['id'].'/archive') ?>"><button class="button button-small button-danger" type="submit">Archive</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
